/* Focused harness prelude: minimal definitions so the *actual* target
 * g_string_expand()/g_string_maybe_expand() bodies can be compiled and
 * exercised. This is NOT a replacement for a full GLib build; it isolates
 * the two functions under test. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <stdint.h>

typedef size_t gsize;
typedef char   gchar;

typedef struct _GString
{
  gchar  *str;
  gsize   len;
  gsize   allocated_len;
} GString;

#define G_MAXSIZE ((gsize) -1)
#define G_GSIZE_FORMAT "zu"
#define G_UNLIKELY(expr) (expr)

static int  test_error_count = 0;
static char test_error_msg[256];

static void
test_g_error (const char *format, ...)
{
  va_list ap;
  va_start (ap, format);
  vsnprintf (test_error_msg, sizeof test_error_msg, format, ap);
  va_end (ap);
  test_error_count++;
  fprintf (stderr, "g_error: %s\n", test_error_msg);
}

#define g_error(...) test_g_error (__VA_ARGS__)
#define g_realloc(ptr, sz) realloc ((ptr), (sz))

/* Mirror of glib/gutilsprivate.h g_nearest_pow(). */
static inline gsize
g_nearest_pow (gsize num)
{
  gsize n = num - 1;
  n |= n >> 1;
  n |= n >> 2;
  n |= n >> 4;
  n |= n >> 8;
  n |= n >> 16;
  n |= n >> 32;
  return n + 1;
}

/* ---- extracted from target glib/gstring.c follows ---- */

/* Focused harness driver for the GString overflow-guard fix.
 * Positive path: a normal expansion must not raise a false overflow error.
 * Negative path: the crafted wrap-around case from the upstream commit
 * message must be detected before the `len + len >= allocated_len` compare. */
int
main (void)
{
  int failures = 0;

  /* Positive path: normal, modest expansion. */
  {
    GString s;
    s.str = (gchar *) malloc (64);
    memcpy (s.str, "hello", 6);
    s.len = 5;
    s.allocated_len = 64;
    test_error_count = 0;
    g_string_maybe_expand (&s, 100);   /* 5 + 100 >= 64 -> expand */
    if (test_error_count != 0)
      {
        printf ("POSITIVE_FAIL false_positive\n");
        failures++;
      }
    else if (s.allocated_len < 5 + 100 + 1)
      {
        printf ("POSITIVE_FAIL not_expanded\n");
        failures++;
      }
    else
      {
        printf ("POSITIVE_OK allocated_len=%zu\n", s.allocated_len);
      }
    free (s.str);
  }

  /* Negative path: string->len + allocated_len == G_MAXSIZE/2 + 1 and an
   * append of G_MAXSIZE/2. `len + len` wraps to 0, which is < allocated_len,
   * so the pre-comparison check is the only guard that can see the overflow. */
  {
    GString s;
    s.str = (gchar *) (uintptr_t) 1;   /* fault if expansion is attempted */
    s.len = G_MAXSIZE / 2 + 1;
    s.allocated_len = G_MAXSIZE / 2 + 1;
    test_error_count = 0;
    g_string_maybe_expand (&s, G_MAXSIZE / 2);
    if (test_error_count == 1)
      {
        printf ("NEGATIVE_DETECTED\n");
      }
    else
      {
        printf ("NEGATIVE_MISSED overflow guard did not fire (%d)\n",
                test_error_count);
        failures++;
      }
  }

  return failures == 0 ? 0 : 1;
}

